# Remove duplicates from support file map
python3 -c "
import sys
lines = open('references/finch-support-map.md').readlines()
seen = set()
out = []
for line in lines:
    if line.startswith('||') or line.startswith('##') or line.strip() == '' or line == '\\n':
        out.append(line)
        continue
    if '|' in line and 'When to read' in line:
        out.append(line)
        continue
    if line in seen:
        continue
    seen.add(line)
    out.append(line)
with open('references/finch-support-map.md', 'w') as f:
    f.writelines(out)
"

